  info:'M12 11v6m0-10h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', edit:'m15 5 4 4M4 20l4-1L21 6a2.8 2.8 0 0 0-4-4L4 15z', send:'m22 2-7 20-4-9-9-4zM22 2 11 13',
